    public static List<String> getHindiCategories() {
        Set<String> cats = new LinkedHashSet<>();
        for (Question q : getAllQuestions()) {
            String cat = q.getCategory();
            if (!cat.endsWith("[EN]")) cats.add(cat);
        }
        return new ArrayList<>(cats);
    }

    public static List<String> getEnglishCategories() {
        Set<String> cats = new LinkedHashSet<>();
        for (Question q : getAllQuestions()) {
            String cat = q.getCategory();
            if (cat.endsWith("[EN]")) cats.add(cat);
        }
        return new ArrayList<>(cats);
    }

    public static List<Question> getByCategory(String category) {
        List<Question> result = new ArrayList<>();
        for (Question q : getAllQuestions()) {
            if (q.getCategory().equals(category)) result.add(q);
        }
        Collections.shuffle(result);
        return result;
    }

    public static int countByCategory(String category) {
        int c = 0;
        for (Question q : getAllQuestions()) if (q.getCategory().equals(category)) c++;
        return c;
    }
